    def maxHappyGroups(self, batchSize, groups):
        reminder = [0] * batchSize
        for g in groups:
            reminder[g % batchSize] += 1

        # Greedy for reminder is zero and two groups reminder is zero.
        result = reminder[0]

        for i in range(1, batchSize // 2 + 1):
