                continue

            m = (reminder[i] // 2) if i == batchSize - i else min(reminder[i], reminder[batchSize - i])

            reminder[i] -= m
            reminder[batchSize - i] -= m
            result += m

        cache = {}
        result += self.dfs(reminder, batchSize, 0, cache)
        return result

    def dfs(self, reminder, batchSize, sum_val, cache):
        key = tuple(reminder)
        if key in cache:
